// O webhook entrega o corpo em `body`. Aqui viram campos planos, e o resto
// do workflow não precisa saber como o painel monta o payload.
return $input.all().map((item) => {
  const b = item.json.body ?? item.json;
  return {
    json: {
      conversationId: b.conversationId,
      waId: b.from ?? null,
      nome: b.profileName ?? 'cliente',
      tipo: b.type ?? 'text',
      texto: (b.text ?? '').trim(),
    },
  };
});
